    image: "/poi-images/ke-times-tower-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Der Times Tower, offiziell als New Central Bank Tower bekannt, ist ein markanter Wolkenkratzer im Herzen des zentralen Geschäftsviertels von Nairobi. Mit einer Höhe von 140 Metern und 38 Stockwerken war er nach seiner Fertigstellung im Jahr 2000 für mehrere Jahre das höchste Gebäude in Ostafrika. Das Gebäude dient primär als Hauptsitz der Kenya Revenue Authority (KRA) und beherbergt zahlreiche Büros der Steuerbehörde. Die Architektur zeichnet sich durch eine moderne Betonstruktur und eine markante Fassadengestaltung aus, die das Stadtbild von Nairobi nachhaltig geprägt hat. Es ist ein zentraler Knotenpunkt für Finanzverwaltung und Steuerwesen in Kenia. Aufgrund seiner strategischen Bedeutung unterliegt das Gebäude strengen Sicherheitsvorkehrungen und ist für die Öffentlichkeit nur eingeschränkt zugänglich. Die Konstruktion wurde mit speziellen Maßnahmen zur Erdbebensicherheit und modernen Belüftungssystemen ausgestattet.",
      hu: "A Times Tower, hivatalos nevén New Central Bank Tower, Nairobi központi üzleti negyedének egyik legmeghatározóbb felhőkarcolója. A 140 méter magas, 38 emeletes épület 2000-es átadásakor Kelet-Afrika legmagasabb építményének számított, és éveken át őrizte ezt a címet. Az épület elsősorban a Kenya Revenue Authority (KRA), azaz a kenyai adóhatóság központjaként funkcionál, számos hivatali irodának helyet adva. Építészeti stílusa a modernizmust képviseli, betonvázas szerkezete és jellegzetes külső megjelenése a városi látkép fontos elemévé tette. Fontos szerepet tölt be Kenya pénzügyi igazgatásában és gazdasági életében. Stratégiai jelentősége miatt az épületet szigorú biztonsági protokollok védik, és a látogatók számára csak korlátozottan látogatható. Az építkezés során kiemelt figyelmet fordítottak a szeizmikus stabilitásra és a korszerű infrastrukturális megoldásokra.",
      ro: "Times Tower, cunoscut oficial sub numele de New Central Bank Tower, este un zgârie-nori emblematic situat în districtul financiar central din Nairobi. Cu o înălțime de 140 de metri și 38 de etaje, clădirea a deținut titlul de cea mai înaltă structură din Africa de Est timp de câțiva ani după finalizarea sa în anul 2000. Imobilul servește drept sediu principal pentru Kenya Revenue Authority (KRA), găzduind birourile centrale ale administrației fiscale naționale. Arhitectura sa modernă, bazată pe o structură de beton armat, a redefinit linia orizontului capitalei kenyene la începutul mileniului. Clădirea reprezintă un punct vital pentru administrarea financiară și colectarea veniturilor statului kenyan. Din cauza importanței sale strategice, accesul publicului este strict monitorizat prin măsuri de securitate riguroase. Proiectul a inclus tehnologii avansate pentru stabilitate structurală și sisteme eficiente de climatizare adaptate regiunii.",
      en: "Times Tower, also known as the New Central Bank Tower, is a prominent skyscraper located in the central business district of Nairobi. Standing at a height of 140 meters with 38 floors, it was the tallest building in East Africa for several years following its completion in 2000. The building primarily serves as the headquarters for the Kenya Revenue Authority (KRA), housing the administrative offices responsible for national tax collection. Its architectural design features a modern concrete structure that has become a staple of the Nairobi skyline. The tower plays a critical role in Kenya's financial infrastructure and economic governance. Due to its strategic importance, the facility maintains high-level security protocols and offers limited access to the general public. The construction utilized specialized engineering techniques to ensure seismic stability and efficient vertical transportation within the tower.",
      es: "La Times Tower es un rascacielos sobrio y muy marcado en el núcleo administrativo de Nairobi. Con su altura de 140 metros y 38 plantas, fue durante mucho tiempo el símbolo más visible de la administración financiera estatal en Kenia. El edificio, terminado en el año 2000, alberga la Autoridad Fiscal de Kenia y por ello está estrictamente vigilado. Su forma clara y brutal lo convierte menos en un destino turístico que en un signo de poder de la burocracia. En la imagen urbana, la torre marca la transición del antiguo paisaje del CBD a una capital vertical y moderna.",
      pt: "A Times Tower é um arranha-céus sóbrio e muito marcante no núcleo administrativo de Nairobi. Com os seus 140 metros de altura e 38 andares, foi durante muito tempo o símbolo mais visível da administração financeira estatal no Quénia. O edifício, concluído no ano 2000, alberga a Autoridade Tributária do Quénia (KRA) e, por isso, é rigorosamente vigiado. A sua forma clara e brutal torna-o menos um destino turístico e mais um sinal de poder da burocracia. Na paisagem urbana, a torre marca a transição da antiga área do CBD para uma capital vertical e moderna.",
      fr: "La Times Tower est un gratte-ciel sobre et très imposant situé dans le centre administratif de Nairobi. Avec sa hauteur de 140 mètres et ses 38 étages, elle a longtemps été le symbole le plus visible de l'administration financière de l'État au Kenya. Le bâtiment, achevé en 2000, abrite la Kenya Revenue Authority et est donc strictement gardé. Sa forme claire et brute en fait moins une destination touristique qu'un signe du pouvoir de la bureaucratie. Dans le paysage urbain, la tour marque la transition entre l'ancien paysage du CBD et une capitale verticale moderne.",
    },
