      es: ["Inaugurado en 2021.", "Seis torres en el complejo.", "Torre más alta de 184 metros.", "43 pisos en la torre principal.", "JW Marriott parte del proyecto.", "Situado en el barrio de Westlands.", "Uno de los proyectos inmobiliarios más grandes de África Oriental."],
