    type: "landmark",
    parent: "KE-30",
    coords: [36.8258, -1.3039],
    name: {
      de: "Nyayo Nationalstadion",
      hu: "Nyayo Nemzeti Stadion",
      ro: "Stadionul Național Nyayo",
      en: "Nyayo National Stadium"},
    image: "/poi-images/ke-nyayo-national-stadium-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Das Nyayo National Stadium ist ein bedeutendes Mehrzweckstadion in Nairobi, Kenia, das sich direkt am Rande des zentralen Geschäftsviertels befindet. Es wurde im Jahr 1983 unter der Regierung von Präsident Daniel arap Moi fertiggestellt und verfügt über eine Kapazität von etwa 30.000 Zuschauern. Das Stadion dient als regelmäßiger Austragungsort für nationale Feierlichkeiten, Fußballspiele und Leichtathletikwettbewerbe. Es ist die Heimspielstätte mehrerer kenianischer Fußballvereine und war Schauplatz zahlreicher internationaler Begegnungen. Neben dem Hauptspielfeld umfasst der Komplex eine Sporthalle, ein olympisches Schwimmbecken und Handballplätze. In den letzten Jahren wurden umfangreiche Renovierungsarbeiten durchgeführt, um das Stadion an internationale Standards für Sicherheits- und Medienanforderungen anzupassen. Das Stadion spielt eine zentrale Rolle im kenianischen Sportleben und ist ein wichtiger Identifikationspunkt für die Bewohner der Hauptstadt.",
      hu: "A Nyayo Nemzeti Stadion Nairobi egyik legfontosabb többfunkciós sportlétesítménye, amely közvetlenül a központi üzleti negyed szélén található. Az 1983-ban, Daniel arap Moi elnök idején elkészült stadion körülbelül 30 000 néző befogadására alkalmas. A létesítmény rendszeresen ad otthont nemzeti ünnepeknek, labdarúgó-mérkőzéseknek és atlétikai versenyeknek. Számos kenyai futballklub hazai pályájaként szolgál, és számos nemzetközi mérkőzés helyszíne volt. A főpálya mellett a komplexum magában foglal egy sportcsarnokot, egy olimpiai méretű úszómedencét és kézilabdapályákat is. Az elmúlt években jelentős felújításokon esett át, hogy megfeleljen a nemzetközi biztonsági és médiaügyi előírásoknak. A stadion központi szerepet játszik Kenya sportéletében, és a főváros lakói számára fontos közösségi és kulturális találkozóhely.",
      ro: "Stadionul Național Nyayo este o facilitate sportivă multifuncțională majoră din Nairobi, Kenya, situată la marginea districtului central de afaceri. A fost finalizat în anul 1983, sub administrația președintelui Daniel arap Moi, și are o capacitate de aproximativ 30.000 de spectatori. Stadionul servește drept locație regulată pentru festivități naționale, meciuri de fotbal și competiții de atletism. Este terenul propriu pentru mai multe cluburi de fotbal din Kenya și a găzduit numeroase întâlniri internaționale importante. Pe lângă terenul principal, complexul include o sală de sport acoperită, o piscină olimpică și terenuri de handbal. În ultimii ani, au fost efectuate renovări extinse pentru a alinia stadionul la standardele internaționale de siguranță și cerințe media. Stadionul joacă un rol central în viața sportivă a Kenyei și este un punct de referință istoric pentru locuitorii capitalei.",
      en: "Nyayo National Stadium is a significant multi-purpose stadium in Nairobi, Kenya, situated right at the edge of the Central Business District. It was completed in 1983 under the government of President Daniel arap Moi and has a seating capacity of approximately 30,000. The stadium serves as a frequent venue for national celebrations, football matches, and athletics competitions. It is the home ground for several Kenyan football clubs and has hosted numerous high-profile international matches. In addition to the main pitch, the complex includes an indoor gymnasium, an Olympic-size swimming pool, and handball courts. In recent years, extensive renovations have been carried out to upgrade the facility to international standards for safety and media requirements. The stadium plays a central role in Kenya's sporting culture and serves as a vital gathering place for the capital's residents during major public events.",
      es: "El Estadio Nacional Nyayo es un lugar clave para el deporte en Nairobi y está situado en uno de los cruces más transitados de la capital. Se inauguró en 1983 y puede albergar a unos 30.000 espectadores. Además de fútbol y atletismo, la instalación sirve también de escenario para celebraciones nacionales y grandes eventos políticos. El complejo incluye además una piscina olímpica y un pabellón para deportes de interior. De este modo, el estadio no es solo un lugar de juego, sino un espacio público polifacético.",
      pt: "O Estádio Nacional Nyayo é um local fundamental para o desporto em Nairobi e situa-se num dos cruzamentos mais movimentados da capital. Foi inaugurado em 1983 e pode acolher cerca de 30.000 espectadores. Além do futebol e atletismo, a instalação serve também de palco para celebrações nacionais e grandes eventos políticos. O complexo inclui ainda uma piscina olímpica e um pavilhão para desportos de interior. Desta forma, o estádio não é apenas um local de jogo, mas um espaço público multifacetado.",
      fr: "Le stade national Nyayo est un lieu clé pour le sport à Nairobi, situé à l'un des carrefours les plus fréquentés de la capitale. Il a été inauguré en 1983 et peut accueillir environ 30 000 spectateurs. Outre le football et l'athlétisme, l'installation sert également de scène pour des célébrations nationales et de grands événements politiques. Le complexe comprend aussi une piscine olympique et une salle de sport intérieure. Ainsi, le stade n'est pas seulement un terrain de jeu, mais un espace public polyvalent.",
    },
