      es: ["Inaugurado en 1999.", "Primer templo BAPS en África construido según los Shilpa Shastras indios tradicionales.", "Las piedras fueron talladas en la India y enviadas a Kenia."],
      pt: ["Inaugurado em 1999.", "O primeiro templo BAPS em África construído de acordo com os tradicionais Shilpa Shastras indianos.", "As pedras foram esculpidas na Índia e enviadas para o Quénia."],
