    type: "landmark",
    parent: "KE-30",
    coords: [36.8225, -1.2878],
    name: {
      de: "Oberster Gerichtshof Kenia",
      hu: "Kenya Legfelsőbb Bírósága",
      ro: "Curtea Supremă din Kenya",
      en: "Supreme Court of Kenya"},
    image: "/poi-images/ke-supreme-court-kenya-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Das Gebäude des Supreme Court of Kenya in Nairobi ist ein historisches Juwel der neoklassizistischen Architektur und ein Symbol für die Justizgeschichte des Landes. Es wurde 1935 während der britischen Kolonialherrschaft als Sitz der Law Courts errichtet und diente jahrzehntelang als höchstes Gericht der Kolonie und später der Republik. Das Bauwerk besticht durch seine monumentalen Säulen, die symmetrische Fassade und die Verwendung von lokalem Stein, was ihm eine zeitlose Erhabenheit verleiht. Nach der Verabschiedung der neuen Verfassung im Jahr 2011 wurde es offiziell zum Sitz des neu geschaffenen Obersten Gerichtshofs ernannt. Das Gebäude befindet sich in der Nähe des City Square und ist von anderen wichtigen Regierungsgebäuden umgeben. Im Inneren beherbergt es historische Gerichtssäle, in denen bedeutende Prozesse der kenianischen Geschichte stattfanden. Heute steht es nicht nur für die Rechtsstaatlichkeit, sondern ist auch ein geschütztes nationales Denkmal, das die Entwicklung des kenianischen Justizsystems dokumentiert.",
      hu: "A nairobi Legfelsőbb Bíróság épülete a neoklasszicista építészet történelmi gyöngyszeme és Kenya igazságszolgáltatási múltjának szimbóluma. 1935-ben épült a brit gyarmati uralom idején, eredetileg a gyarmat központi bíróságának (Law Courts) székhelyeként. Az épületet monumentális oszlopok, szimmetrikus homlokzat és helyi kőzet használata jellemzi, ami időtlen méltóságot kölcsönöz neki. A 2011-es új alkotmány elfogadása után az épület hivatalosan is az újonnan létrehozott Legfelsőbb Bíróság otthona lett. A City Square közelében található komplexumot fontos kormányzati épületek veszik körül. A belső terekben történelmi tárgyalótermek találhatók, ahol Kenya történelmének legfontosabb jogi ügyeit tárgyalták. Napjainkban az épület nemcsak a jogállamiság jelképe, hanem védett nemzeti műemlék is, amely hűen tükrözi a kenyai igazságszolgáltatási rendszer fejlődését és modernizációját.",
      ro: "Clădirea Curții Supreme a Kenyei din Nairobi este o bijuterie istorică a arhitecturii neoclasice și un simbol al istoriei judiciare a țării. Construită în 1935, în timpul administrației coloniale britanice, clădirea a servit inițial ca sediu al Tribunalelor (Law Courts). Impunătoarea structură se remarcă prin coloanele sale monumentale, fațada simetrică și utilizarea pietrei locale, oferindu-i o prezență solemnă și atemporală. Odată cu adoptarea noii Constituții în 2011, edificiul a fost desemnat oficial sediul nou-înființatei Curți Supreme. Situată în apropierea pieței City Square, clădirea este înconjurată de alte instituții guvernamentale de importanță majoră. În interior, sălile de judecată păstrează o atmosferă istorică, fiind locul unde s-au desfășurat procese cruciale pentru evoluția statului kenyan. Astăzi, clădirea nu reprezintă doar autoritatea legii, ci este și un monument național protejat, martor al transformărilor sistemului juridic național.",
      en: "The Supreme Court of Kenya building in Nairobi is a historic gem of neoclassical architecture and a symbol of the nation's judicial history. It was constructed in 1935 during the British colonial era to serve as the Law Courts of Nairobi. The structure is characterized by its monumental columns, symmetrical facade, and the use of local stone, which gives it a sense of timeless authority. Following the adoption of the new Constitution in 2011, it was officially designated as the seat of the newly established Supreme Court. Located near City Square, the building is surrounded by other significant government institutions. Inside, it houses historic courtrooms that have witnessed pivotal legal cases in Kenyan history. Today, the building stands not only as a place of law but also as a protected national monument, documenting the evolution of the Kenyan justice system from the colonial period to the modern democratic era.",
      es: "El edificio del Tribunal Supremo de Kenia marca el punto más alto de la justicia keniana. Se encuentra en la City Square de Nairobi y fue construido en los años 30 como tribunal superior colonial. La estricta fachada neoclásica con columnas y pórticos se diseñó para irradiar autoridad y permanencia. Hoy, aquí se reúne el Tribunal Supremo, compuesto por siete miembros, que desempeña un papel central especialmente en cuestiones constitucionales y elecciones presidenciales. El edificio muestra con qué fuerza la arquitectura en Kenia hace visible el poder institucional.",
      pt: "O edifício do Supremo Tribunal do Quénia marca o ponto mais alto da justiça queniana. Situa-se na City Square de Nairobi e foi construído nos anos 1930 como edifício do tribunal superior colonial. A rigorosa fachada neoclássica com colunas e pórticos foi desenhada para irradiar autoridade e durabilidade. Hoje, reúne-se aqui o Supremo Tribunal de sete membros, que desempenha um papel central especialmente em questões constitucionais e eleições presidenciais. A construção mostra como a arquitetura no Quénia torna visível o poder institucional.",
      fr: "Le bâtiment de la Cour suprême du Kenya marque le sommet de la justice kényane. Il se dresse sur City Square à Nairobi et a été construit dans les années 1930 comme bâtiment de la Haute Cour coloniale. La façade néoclassique stricte avec ses colonnes et ses portiques a été conçue pour dégager autorité et pérennité. Aujourd'hui, la Cour suprême, composée de sept juges, y siège et joue un rôle central, notamment pour les questions constitutionnelles et les élections présidentielles. L'édifice illustre la force avec laquelle l'architecture au Kenya rend visible le pouvoir institutionnel.",
    },
