    type: "landmark",
    parent: "KE-28",
    coords: [39.6644, -4.062],
    name: {
      de: "Mombasa Tusks",
      hu: "Mombasa Agyarak",
      ro: "Colții din Mombasa",
      en: "Mombasa Tusks"},
    image: "/poi-images/ke-mombasa-tusks-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Die Mombasa Tusks sind das ikonischste Wahrzeichen der Küstenstadt Mombasa und befinden sich an der Moi Avenue. Diese monumentalen Aluminiumkonstruktionen wurden 1952 errichtet, um den Besuch der britischen Prinzessin Elizabeth zu ehren, die während dieser Reise nach dem Tod ihres Vaters zur Königin wurde. Ursprünglich aus Holz und Leinwand gefertigt, wurden sie 1956 durch die heutigen, dauerhaften Metallstrukturen ersetzt. Die vier Stoßzähne bilden zwei Bögen über der Fahrbahn und sind so angeordnet, dass sie aus der Vogelperspektive den Buchstaben 'M' für Mombasa formen. Entgegen einem weit verbreiteten Missverständnis bestehen sie nicht aus echtem Elfenbein, sondern symbolisieren den historischen Hafenstatus der Stadt. Sie markieren den Eingang zum Stadtzentrum und zum Hafenbereich und sind ein unverzichtbares Fotomotiv für Besucher. Heute stehen sie unter dem Schutz der Nationalmuseen von Kenia und repräsentieren den historischen und kulturellen Geist der Stadt.",
      hu: "A Mombasai Agyarak a tengerparti város legikonikusabb jelképei, amelyek a Moi Avenue felett magasodnak. Ezeket a monumentális alumínium szerkezeteket 1952-ben állították fel Erzsébet brit hercegnő látogatásának tiszteletére, aki éppen ezen az úton vált királynővé apja halála után. Az eredetileg fából és vászonból készült agyarakat 1956-ban váltották fel a mai, tartós fémszerkezetek. A négy agyar két ívet alkot az úttest felett, és úgy helyezkednek el, hogy felülnézetből az 'M' betűt formázzák Mombasa tiszteletére. A közhiedelemmel ellentétben nem valódi elefántcsontból készültek, hanem a város történelmi kikötői státuszát és kereskedelmi jelentőségét szimbolizálják. Az agyarak a városközpont és a kikötői negyed bejáratát jelzik, és a turisták számára elengedhetetlen fotópontot jelentenek. Ma a Kenyai Nemzeti Múzeumok védelme alatt állnak, és a város történelmi és kulturális örökségét képviselik.",
      ro: "Colții din Mombasa (Mombasa Tusks) sunt cel mai emblematic punct de reper al orașului de coastă, fiind situați pe bulevardul Moi Avenue. Aceste construcții monumentale din aluminiu au fost ridicate în 1952 pentru a onora vizita prințesei britanice Elisabeta, care a devenit regină în timpul acelei călătorii, în urma decesului tatălui său. Realizați inițial din lemn și pânză, colții au fost înlocuiți în 1956 cu structurile metalice durabile de astăzi. Cei patru colți formează două arcuri deasupra carosabilului și sunt dispuși astfel încât, priviți de sus, să formeze litera 'M' de la Mombasa. Contrar unor concepții greșite, aceștia nu sunt făcuți din fildeș real, ci simbolizează statutul istoric de port și importanța comercială a orașului. Ei marchează intrarea către centrul orașului și zona portuară, fiind un loc de fotografiat indispensabil pentru vizitatori. Astăzi, monumentul se află sub protecția Muzeelor Naționale din Kenya, reprezentând spiritul istoric și cultural al metropolei.",
      en: "The Mombasa Tusks are the most iconic landmark of the coastal city of Mombasa, spanning across Moi Avenue. These monumental aluminum structures were erected in 1952 to commemorate the visit of Princess Elizabeth of Britain, who became Queen during that very trip following the death of her father. Originally made from wood and canvas, the tusks were replaced in 1956 with the permanent metal structures seen today. The four tusks form two interlaced arches over the road, arranged in a way that they form the letter 'M' for Mombasa when viewed from above. Contrary to common misconceptions, they are not made of real ivory but are symbolic of the city's historical status as a major gateway and trading port. They mark the entrance to the city center and the harbor area, serving as a must-visit photo spot for tourists. Today, the monument is protected by the National Museums of Kenya and represents the historic and cultural spirit of the city.",
      es: "Los Mombasa Tusks son el motivo fotográfico más famoso de la ciudad costera y marcan la avenida Moi en pleno centro. Construidos originalmente en 1952 con madera y lona para la visita de la princesa Isabel, más tarde fueron sustituidos por estructuras estables de aluminio. Los cuatro colmillos forman deliberadamente la letra M de Mombasa, funcionando a la vez como logotipo de la ciudad y arco vial. El monumento no es tanto un museo como una imagen potente en el espacio urbano que vincula la historia colonial, la memoria y el turismo.",
      pt: "Os Mombasa Tusks são o motivo fotográfico mais famoso da cidade costeira e marcam a Avenida Moi em pleno centro. Originalmente construídos em 1952 com madeira e lona para a visita da Princesa Elizabeth, foram posteriormente substituídos por estruturas estáveis de alumínio. As quatro presas formam deliberadamente a letra M de Mombaça, funcionando simultaneamente como logótipo da cidade e arco de estrada. O monumento é menos um museu e mais uma imagem forte no espaço urbano que liga a história colonial, a memória e o turismo.",
      fr: "Les Mombasa Tusks sont le motif photographique le plus célèbre de la ville côtière et marquent l'avenue Moi en plein centre. Initialement érigés en 1952 en bois et toile pour la visite de la princesse Elizabeth, ils ont ensuite été remplacés par des structures stables en aluminium. Les quatre défenses forment délibérément la lettre M pour Mombasa, fonctionnant ainsi à la fois comme logo de la ville et arc routier. Le monument est moins un musée qu'une image forte dans l'espace urbain, reliant l'histoire coloniale, la mémoire et le tourisme.",
    },
