      hu: ["1952-ben állították fel Erzsébet hercegnőnek", "Alumíniumból készültek, nem elefántcsontból", "Felülnézetből egy 'M' betűt formáznak", "Mombasában, a Moi Avenue-n találhatók", "A tartós fémszerkezet 1956 óta áll", "A Kenyai Nemzeti Múzeumok felügyelik"],
      ro: ["Ridicați în 1952 pentru prințesa Elisabeta", "Sunt fabricați din aluminiu, nu din fildeș", "Formează litera 'M' văzuți din aer", "Situați pe bulevardul Moi Avenue din Mombasa", "Structura metalică permanentă datează din 1956", "Administrați de Muzeele Naționale din Kenya"],
      en: ["Erected in 1952 for Princess Elizabeth's visit", "Made of aluminum, not real ivory", "Form the letter 'M' for Mombasa from above", "Located on Moi Avenue in Mombasa", "Permanent metal structures installed in 1956", "Protected by the National Museums of Kenya"],
      es: ["Erigidos en 1952.", "Construidos para la princesa Isabel.", "Reconstruidos más tarde en aluminio.", "Situados en la avenida Moi de Mombasa.", "Forman la letra M.", "Símbolo de la ciudad de Mombasa.", "Uno de los motivos más fotografiados de la costa."],
      pt: ["Erguidos em 1952.", "Construídos para a Princesa Elizabeth.", "Reconstruídos posteriormente em alumínio.", "Situados na Avenida Moi em Mombaça.", "Formam a letra M.", "Símbolo da cidade de Mombaça.", "Um dos motivos mais fotografados da costa."],
      fr: ["Érigés en 1952.", "Construits pour la princesse Elizabeth.", "Reconstruits plus tard en aluminium.", "Situés sur l'avenue Moi à Mombasa.", "Forment la lettre M.", "Symbole de la ville de Mombasa.", "L'un des motifs les plus photographiés de la côte."],
