      en: ["The current bridge was completed in 1980", "Total length is 391.5 meters", "Replaced a pontoon bridge from 1931", "Spans over the Tudor Creek in Mombasa", "Primary link to Nyali and the North Coast", "Prestressed concrete box girder construction"],
      es: ["Terminado en 1980.", "Construido con ayuda japonesa.", "Cruza el arroyo Tudor.", "Conecta la isla de Mombasa con tierra firme.", "Ruta importante hacia la costa norte.", "Sustituyó a una antigua conexión de pontones.", "Seis carriles soportan un tráfico denso."],
