    name: {
      de: "Mandhry Moschee",
      hu: "Mandhry Mecset",
      ro: "Moscheea Mandhry",
      en: "Mandhry Mosque"},
    image: "/poi-images/ke-mandhry-mosque-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Die Mandhry-Moschee ist eine der ältesten und bedeutendsten Moscheen in Mombasa und ein herausragendes Beispiel für die Swahili-Architektur. Sie wurde im Jahr 1570 erbaut und befindet sich im Herzen der historischen Altstadt (Old Town), unweit des alten Hafens. Das Gebäude zeichnet sich durch seine schlichte Eleganz, die dicken Korallensteinwände und das ikonische Minarett aus, das eine markante spiralförmige Form aufweist. Seit Jahrhunderten dient die Moschee als spirituelles Zentrum für die lokale Gemeinschaft und ist bis heute ununterbrochen in Betrieb. Die Architektur verbindet afrikanische, arabische und indische Einflüsse, was typisch für die Küstenkultur Ostafrikas ist. Im Inneren ist die Moschee für ihre kühle Atmosphäre und die filigranen Holzschnitzereien bekannt. Als geschütztes historisches Denkmal erzählt sie die Geschichte des Islam an der kenianischen Küste und der jahrhundertealten Handelsbeziehungen im Indischen Ozean.",
      hu: "A Mandhry-mecset Mombasa egyik legrégebbi és legjelentősebb mecsete, a szuahéli építészet kiemelkedő példája. 1570-ben épült, és a történelmi óváros (Old Town) szívében található, nem messze a régi kikötőtől. Az épületet letisztult elegancia, vastag korallkő falak és az ikonikus, spirális formájú minaret jellemzi. Évszázadok óta szolgál a helyi közösség spirituális központjaként, és a mai napig folyamatosan működik. Az építészet ötvözi az afrikai, arab és indiai hatásokat, ami jellemző Kelet-Afrika tengerparti kultúrájára. Belül a mecset hűvös atmoszférájáról és finom fafaragásairól ismert. Védett történelmi műemlékként mesél az iszlám kenyai tengerparton betöltött szerepéről és az Indiai-óceán évszázados kereskedelmi kapcsolatairól. A látogatók számára a mecset bepillantást enged Mombasa gazdag történelmi múltjába és vallási hagyományaiba.",
      ro: "Moscheea Mandhry este una dintre cele mai vechi și mai importante moschei din Mombasa, fiind un exemplu remarcabil de arhitectură Swahili. Construită în anul 1570, aceasta este situată în inima orașului vechi (Old Town), în apropierea portului istoric. Edificiul se distinge prin eleganța sa sobră, zidurile groase din piatră de corali și minaretul său iconic, care prezintă o formă spiralată distinctivă. Timp de secole, moscheea a servit ca centru spiritual pentru comunitatea locală și rămâne în funcțiune neîntreruptă până în prezent. Arhitectura sa îmbină influențe africane, arabe și indiene, reflectând amestecul cultural unic specific coastei est-africane. În interior, moscheea este renumită pentru atmosfera sa răcoroasă și pentru detaliile sculptate în lemn. Ca monument istoric protejat, moscheea Mandhry depune mărturie despre istoria islamului pe coasta kenyană și despre vechile rute comerciale din Oceanul Indian.",
      en: "The Mandhry Mosque is one of the oldest and most significant mosques in Mombasa, standing as a prime example of Swahili architecture. Built in 1570, it is located in the heart of the historic Old Town, close to the Old Port. The building is characterized by its simple elegance, thick coral stone walls, and an iconic minaret featuring a distinctive spiral staircase design. For centuries, the mosque has served as a spiritual center for the local community and continues to be in active use today. Its architecture blends African, Arabic, and Indian influences, reflecting the unique coastal culture of East Africa. Inside, the mosque is known for its cool atmosphere and intricate woodwork. As a protected historical monument, it tells the story of Islam on the Kenyan coast and the centuries-old Indian Ocean trade networks that shaped the region's identity.",
      es: "La Mezquita Mandhry se encuentra en lo profundo del casco antiguo de Mombasa y es una de las mezquitas más antiguas todavía en uso en la costa de África Oriental. Sus raíces se remontan a 1570, y la construcción está hecha de piedra de coral, típica de la arquitectura swahili. Destaca especialmente el minarete cuadrado, que se diferencia claramente de las formas posteriores y más redondeadas. En el patio hay un antiguo pozo y zonas sombreadas para la ablución ritual, por lo que el lugar se mantiene muy vivo hasta hoy.",
      pt: "A Mesquita Mandhry está situada no coração da cidade velha de Mombasa e é uma das mesquitas mais antigas ainda em uso na costa da África Oriental. As suas raízes remontam a 1570 e a construção é feita de pedra de coral, típica da arquitetura Swahili. Particularmente marcante é o minarete quadrado, que difere claramente das formas posteriores e mais arredondadas. No pátio, há um poço antigo e áreas sombreadas para a ablução ritual, o que torna o local muito vibrante até hoje.",
      fr: "La mosquée Mandhry se niche au cœur de la vieille ville de Mombasa et compte parmi les plus anciennes mosquées encore en usage sur la côte est-africaine. Ses origines remontent à 1570, et l'édifice est bâti en pierre de corail, caractéristique de l'architecture swahilie. Son minaret carré est particulièrement remarquable, se distinguant nettement des formes plus tardives et arrondies. Dans la cour, un vieux puits et des zones ombragées pour les ablutions rituelles entretiennent l'atmosphère vivante du site.",
    },
