    type: "landmark",
    parent: "KE-14",
    coords: [39.8475, -3.6391],
    name: {
      de: "Kilifi-Brücke",
      hu: "Kilifi Híd",
      ro: "Podul Kilifi",
      en: "Kilifi Bridge"},
    image: "/poi-images/ke-kilifi-bridge-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Die Kilifi-Brücke ist ein beeindruckendes Ingenieurbauwerk an der kenianischen Küste und war bei ihrer Fertigstellung die längste Brücke des Landes. Sie wurde 1991 mit finanzieller Unterstützung der japanischen Regierung eröffnet und überquert den Kilifi Creek, einen tiefen Meeresarm des Indischen Ozeans. Die Brücke hat eine Gesamtlänge von 420 Metern und ersetzte eine unzuverlässige Fährverbindung, was die Reisezeit zwischen Mombasa und Malindi erheblich verkürzte. Die Konstruktion besteht aus einer modernen Betonbrücke, die auf massiven Pfeilern ruht, die tief im Grund des Creeks verankert sind. Von der Brücke aus hat man einen atemberaubenden Blick auf das türkisfarbene Wasser, die Segelboote der Fischer und die dichten Mangrovenwälder an den Ufern. Sie ist ein entscheidender Faktor für die wirtschaftliche Entwicklung der Region Kilifi und ein wichtiger Teil der Fernstraße B8, die den Norden der Küste erschließt.",
      hu: "A Kilifi-híd lenyűgöző mérnöki alkotás a kenyai tengerparton, amely elkészültekor az ország leghosszabb hídja volt. 1991-ben adták át a japán kormány pénzügyi támogatásával, és a Kilifi-öblöt, az Indiai-óceán egyik mély benyúlását íveli át. A híd teljes hossza 420 méter, és egy korábbi bizonytalan kompjáratot váltott fel, jelentősen lerövidítve a Mombasa és Malindi közötti menetidőt. A szerkezet egy modern betonhíd, amely hatalmas, az öböl aljába mélyen beágyazott pilléreken nyugszik. A hídról lélegzetelállító kilátás nyílik a türkizkék vízre, a halászok vitorlásaira és a part menti sűrű mangroveerdőkre. A híd meghatározó tényező Kilifi régió gazdasági fejlődésében, és a B8-as főút kulcsfontosságú szakasza, amely az északi tengerparti területeket köti össze az ország többi részével.",
      ro: "Podul Kilifi este o realizare impresionantă de inginerie situată pe coasta Kenyei, fiind la momentul finalizării sale cel mai lung pod din țară. Inaugurat în 1991 cu sprijin financiar din partea guvernului Japoniei, podul traversează estuarul Kilifi Creek, o ramificație adâncă a Oceanului Indian. Structura are o lungime totală de 420 de metri și a înlocuit un serviciu de feribot nesigur, reducând semnificativ timpul de călătorie între Mombasa și Malindi. Construcția este un pod modern din beton, sprijinit pe piloni masivi ancorați adânc în fundul apei. De pe pod, vizitatorii pot admira o vedere panoramică asupra apelor turcoaz, a bărcilor de pescuit tradiționale și a pădurilor de mangrove de pe maluri. Podul reprezintă un factor decisiv pentru dezvoltarea economică a regiunii Kilifi și o componentă esențială a autostrăzii B8, care deservește coasta de nord.",
      en: "The Kilifi Bridge is an impressive engineering feat on the Kenyan coast and was the longest bridge in the country at the time of its completion. Opened in 1991 with financial assistance from the Japanese government, the bridge spans the Kilifi Creek, a deep inlet of the Indian Ocean. The structure has a total length of 420 meters and replaced an unreliable ferry service, significantly reducing travel time between Mombasa and Malindi. The design features a modern concrete deck supported by massive pillars anchored deep into the creek bed. From the bridge, travelers are treated to breathtaking views of the turquoise waters, local fishing dhows, and lush mangrove forests lining the shores. It is a critical driver for the economic development of Kilifi County and a key segment of the B8 highway that connects the northern coastal region to the rest of the country.",
      es: "El Kilifi Bridge cruza el profundo Kilifi Creek y es considerado el puente más largo de Kenia. Con un vano de unos 420 metros y terminado en 1991, reemplazó a un lento servicio de ferry que frenaba repetidamente el tráfico costero. Hasta hoy, la construcción mejora la conexión entre la carretera costera y las localidades al norte de Mombasa. Debido a su ubicación sobre el estuario, el puente resulta impresionante tanto técnica como paisajísticamente. Es un buen ejemplo de cómo la infraestructura en la costa desencadena directamente el desarrollo económico.",
      pt: "A Kilifi Bridge atravessa o profundo Kilifi Creek e é considerada a ponte mais longa do Quénia. Com cerca de 420 metros de extensão e concluída em 1991, substituiu uma ligação de ferry lenta que atrasava constantemente o tráfego costeiro. Até hoje, a construção melhora a ligação entre a estrada costeira e as localidades a norte de Mombasa. Devido à sua localização sobre o estuário, a ponte é impressionante tanto técnica como paisagisticamente. É um excelente exemplo de como a infraestrutura na costa impulsiona diretamente o desenvolvimento económico.",
      fr: "Le Kilifi Bridge enjambe le profond Kilifi Creek et est considéré comme le plus long pont du Kenya. D'une portée d'environ 420 mètres et achevé en 1991, il a remplacé un service de ferry lent qui freinait régulièrement le trafic côtier. Aujourd'hui encore, l'ouvrage améliore la liaison entre la route côtière et les localités au nord de Mombasa. Par sa situation au-dessus de l'estuaire, le pont est impressionnant tant sur le plan technique que paysager. Il illustre parfaitement comment les infrastructures côtières déclenchent directement le développement économique.",
    },
