    type: "landmark",
    parent: "KE-28",
    coords: [39.567, -4.015],
    name: {
      de: "Mombasa Terminus (SGR)",
      hu: "Mombasa Terminus (SGR)",
      ro: "Terminalul Mombasa (SGR)",
      en: "Mombasa Terminus (SGR)"},
    image: "/poi-images/ke-mombasa-terminus-sgr-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Der Mombasa Terminus der Standard Gauge Railway (SGR) in Miritini ist der spektakuläre Endpunkt der Bahnstrecke an der kenianischen Küste. Das 2017 eröffnete Gebäude besticht durch seine markante kreisförmige Architektur, die Wellen und konzentrische Kreise im Wasser symbolisiert und so den Bezug zum nahen Indischen Ozean herstellt. Der Bahnhof dient als Hauptdrehkreuz für Reisende, die den Madaraka Express zwischen der Küste und der Hauptstadt Nairobi nutzen. Mit seinen großzügigen Glasfassaden und der modernen Innenausstattung bietet der Terminus einen Komfort, der weit über den alten Bahnstandards in der Region liegt. Er liegt etwas außerhalb des Stadtzentrums von Mombasa und ist durch Zubringerbusse und Taxis gut erschlossen. Die Station spielt eine Schlüsselrolle bei der Förderung des Küstentourismus, da sie eine schnelle und sichere Alternative zur strapaziösen Busfahrt bietet. Als Teil der neuen Seidenstraße in Afrika ist der Bahnhof ein Symbol für den wirtschaftlichen Aufschwung der Hafenstadt.",
      hu: "A mombasai SGR vasútállomás Miritini-ben a vasútvonal látványos végpontja a kenyai tengerparton. A 2017-ben megnyitott épület különleges, kör alakú építészetével tűnik ki, amely a vizet és a koncentrikus köröket szimbolizálja, utalva a közeli Indiai-óceánra. Az állomás a fő csomópontja a tengerpart és a főváros, Nairobi között közlekedő Madaraka Express utasainak. Tágas üvegfelületeivel és modern belső kialakításával olyan kényelmet nyújt, amely messze meghaladja a régió korábbi vasúti szabványait. Az állomás Mombasa városközpontján kívül helyezkedik el, de transzferbuszokkal és taxikkal jól megközelíthető. Kulcsszerepet játszik a tengerparti turizmus fellendítésében, mivel gyors és biztonságos alternatívát kínál a kimerítő buszos utazással szemben. Az afrikai 'új selyemút' részeként az állomás a kikötőváros gazdasági fellendülésének és modernizációjának jelképe.",
      ro: "Terminalul Mombasa al căii ferate SGR, situat în Miritini, este punctul terminus spectaculos al liniei ferate de pe coasta Kenyei. Inaugurată în 2017, clădirea impresionează prin arhitectura sa circulară distinctivă, care simbolizează valurile și cercurile concentrice din apă, făcând trimitere la proximitatea Oceanului Indian. Gara servește drept nod principal pentru călătorii care utilizează serviciul Madaraka Express între litoral și capitala Nairobi. Cu fațade ample de sticlă și dotări interioare moderne, terminalul oferă un nivel de confort care depășește standardele feroviare anterioare din regiune. Situat la periferia orașului Mombasa, terminalul este bine conectat prin servicii de transfer și taxiuri. Stația joacă un rol-cheie în stimularea turismului de coastă, oferind o alternativă rapidă și sigură la călătoriile lungi cu autocarul. Ca parte a noii infrastructuri strategice din Africa, gara este un simbol al revigorării economice a orașului portuar.",
      en: "The Mombasa Terminus of the Standard Gauge Railway (SGR), located in Miritini, is the spectacular coastal end of the rail line. Opened in 2017, the building stands out with its striking circular architecture, which symbolizes ripples and concentric circles in the water, reflecting its proximity to the Indian Ocean. The station serves as the main hub for travelers using the Madaraka Express service between the coast and the capital city, Nairobi. Featuring expansive glass facades and modern interior design, the terminus offers a level of comfort that far exceeds previous rail standards in the region. Although situated slightly outside Mombasa's city center, it is well-connected via shuttle buses and taxis. The station plays a key role in boosting coastal tourism by providing a fast, reliable, and safe alternative to the arduous road journey. As a centerpiece of Kenya's new infrastructure, the terminus is a symbol of the port city's economic resurgence.",
      es: "El Mombasa Terminus es la contraparte marítima de la red SGR y recibe a los viajeros en la costa. Fue terminado en 2017 en el suburbio de Miritini y se ubicó deliberadamente fuera de la estrecha ciudad insular para aliviar el tráfico. Los techos curvos evocan el movimiento de las olas del océano Índico y le dan al edificio una fuerte identidad local. Como punto final del Madaraka Express, la estación procesa diariamente a miles de pasajeros con rutinas claras de seguridad y despacho. El edificio conecta de forma muy directa el paisaje costero y la tecnología de transporte moderna.",
      pt: "O Mombasa Terminus é o homólogo marítimo da rede SGR e acolhe os viajantes na costa. Foi concluído em 2017 no subúrbio de Miritini e está propositadamente localizado fora da estreita cidade insular para aliviar o tráfego. Os telhados curvos evocam o movimento das ondas do Oceano Índico e conferem ao edifício uma forte identidade local. Como ponto final do Madaraka Express, a estação processa diariamente milhares de passageiros com rotinas claras de segurança e embarque. O edifício liga de forma direta a paisagem costeira e a moderna tecnologia de transportes.",
      fr: "Le Mombasa Terminus est le pendant maritime du réseau SGR et accueille les voyageurs sur la côte. Achevé en 2017 dans la banlieue de Miritini, il est volontairement situé à l'écart de l'étroite cité insulaire pour soulager le trafic. Les toits incurvés rappellent le mouvement des vagues de l'océan Indien et confèrent au bâtiment une forte identité locale. En tant que point final du Madaraka Express, la gare accueille chaque jour des milliers de passagers avec des procédures de sécurité et d'embarquement fluides. L'édifice unit de manière très directe le paysage côtier et les technologies de transport modernes.",
    },
