      hu: ["A szobrot 2011-ben avatták fel Nairobi egyik legforgalmasabb utcáján.", "Tom Mboyát 1969. július 5-én gyilkolták meg a Moi Avenue-n.", "Ő alapította az 'Airlift Africa' programot, amely segítette a diákok kijutását az USA-ba.", "Az emlékmű bronzból készült, és hősies tartásban ábrázolja a politikust.", "Mboya mindössze 38 éves volt halálakor, de már világhírű diplomata volt.", "A szobor környezetét 2020-ban felújították a városkép javítása érdekében."],
